import{z as A,x as B,o as r,c as p,q as i,j as E,D as e,d as t,s as n,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"多层膜粗糙与散射","description":"","frontmatter":{"title":"多层膜粗糙与散射","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/multilayer-roughness-scatter.md","filePath":"litho/multilayer-roughness-scatter.md","lastUpdated":1791063341000}'),d={name:"litho/multilayer-roughness-scatter.md"};function m(u,a,h,S,f,D){const s=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="多层膜粗糙与散射" tabindex="-1">多层膜粗糙与散射 <a class="header-anchor" href="#多层膜粗糙与散射" aria-label="Permalink to &quot;多层膜粗糙与散射&quot;">​</a></h1><div class="epigraph"><p>峰值反射率报的是镜面那一束；埃级界面粗糙把带内光打进错误角度，对比以 flare 底座的形式付钱。</p><footer>—— 据 Gullikson / Naulleau 对 EUV 散射与 TIS；Mack 对 flare 的定义</footer></div><p><a href="/litho/collector-cleaning">上一课</a>把收集镜上洗得动的锡清掉。缺口是洗不动的和从来就镀在膜里的：多层界面粗糙。它不挡平均功率那么显眼，却把正确波长送进错误方向。<a href="/litho/euv-flare-ml">EUV flare</a> 已经用成像语言写过底座；本课从等离子体到镜面这条课序，把粗糙写成光学表面的空间频谱。低频面形留给<a href="/litho/mirror-figure-error">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>清洗恢复的是可反应污染物的光学厚度。界面互扩散、沉积颗粒、溅射坑和抛光残留，是多层作为体光栅的相位误差。13.5 nm 下，同样埃级高度的散射截面远大于 193 nm。总积分散射（TIS）从每一面镜子进入光瞳外和视场外，六面投影相乘，暗区被垫高。</p><p>缺口不是再定义 flare，而是：粗糙在哪一段空间频率上、如何同时吃反射率并喂散射。只盯峰值 \\(R\\)，会放过「镜子仍亮、对比已死」。</p><p><span class="marginnote">术语翻译：TIS（总积分散射）把所有「走错方向」的带内光加总成一个比例，大致随 \\((\\sigma/\\lambda)^2\\) 涨——σ 是界面粗糙的高度。λ 从 193 nm 缩到 13.5 nm 小了一个数量级，容许的粗糙高度也得跟着缩，埃级（0.1 纳米级）在这里都是正经指标。</span></p><p><span class="marginnote">带外漏光是错误波长；本课的散射是带内走错角度。剂量环加功率补得了平均 \\(R\\)，补不了 TIS 核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把表面高度谱按空间波长分段：低频面形（figure）改波前与像差；中频（后课 MSFR）改小角度晕和局部杂散；高频改大角度 TIS 和峰值 \\(R\\)。多层还要加界面互相关：钼硅界若复制基底粗糙，等效粗糙沿深度相干叠加，散射比单界面更狠。Gullikson 等用 EUV 散射仪把功率谱密度（PSD）连到带内散射；Naulleau 把掩模和光学的中高频一起写进 LER 预算。</p><p>工艺旋钮在镀膜：离子束或磁控的能量、温度、阻挡层，压互扩散；基底抛光压高频。收集镜的径向周期渐变必须在粗糙之上仍然对准布拉格角，否则散射和失谐一起出现。</p><h3 id="收集镜与投影镜不要共用一个-tis-数" tabindex="-1">收集镜与投影镜不要共用一个 TIS 数 <a class="header-anchor" href="#收集镜与投影镜不要共用一个-tis-数" aria-label="Permalink to &quot;收集镜与投影镜不要共用一个 TIS 数&quot;">​</a></h3><p>收集镜离等离子体近，溅射坑主导中高频，主要改 IF 功率和填充。投影镜在干净腔里，抛光与镀膜复制主导，直接进空中像 flare。把收集镜变暗写成 POB 对比损失，会去洗错一面镜子。分层计量：IF 侧看功率与光瞳，硅片侧看 Kirk 或等价暗垫。</p><p><span class="marginnote">直觉类比：收集镜像离灶台最近的抽油烟机滤网——最先脏，脏了主要表现为「灯变暗」（功率掉）；投影镜像客厅投影仪的镜头，沾一点灰就直接糊到幕布（晶圆图形）上。两处的「脏」成因不同、指标不同，账不能混记。</span></p>',14)),(r(),E(o,null,{default:e(()=>[n(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSD%5B%22%E8%A1%A8%E9%9D%A2%E9%AB%98%E5%BA%A6%20PSD%22%5D%20--%3E%20HF%5B%22%E9%AB%98%E9%A2%91%3A%20TIS%20%E4%B8%8E%E6%8E%89%20R%22%5D%0A%20%20PSD%20--%3E%20MF%5B%22%E4%B8%AD%E9%A2%91%3A%20%E6%99%95%E6%96%91%20%2F%20flare%20%E6%A0%B8%22%5D%0A%20%20PSD%20--%3E%20LF%5B%22%E4%BD%8E%E9%A2%91%3A%20%E9%9D%A2%E5%BD%A2%E5%83%8F%E5%B7%AE%22%5D%0A%20%20HF%20--%3E%20IMG%5B%22%E5%AF%B9%E6%AF%94%E5%BA%95%E5%BA%A7%22%5D%0A%20%20MF%20--%3E%20IMG%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"标量估计里，小粗糙度的 TIS 随 \\((4\\pi\\sigma\\cos\\theta/\\lambda)^2\\) 走。λ 缩小一个数量级，σ 必须一起缩小，否则 TIS 不可接受——这是蔡司要把 EUV 基底做到原子量级光滑的原因，不是「光学工匠癖」。多层的每一界面都贡献；帽层氧化或氢致起泡再加一层时变粗糙，清洗课的不可逆项在这里变成散射合同。",-1)),a[5]||(a[5]=l("p",null,"散射光仍是 13.5 nm，胶会曝光。OPC 可以卷积一个密度相关的 flare 核，前提是核稳定。收集镜随寿命变糙，核会走，全场 CD 指纹跟着走。因此粗糙既是出厂规格，也是运行规格。",-1)),(r(),E(o,null,{default:e(()=>[n(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E5%9F%83%E7%BA%A7%E7%95%8C%E9%9D%A2%E7%B2%97%E7%B3%99%20%CF%83%22%5D%20--%3E%20TIS%5B%22%E5%8D%95%E9%9D%A2%20TIS%20~%20(4%CF%80%CF%83%2F%CE%BB)%C2%B2%22%5D%0A%20%20TIS%20--%3E%20SIX%5B%22%E5%85%AD%E9%9D%A2%E6%8A%95%E5%BD%B1%E9%95%9C%E4%B8%B2%E8%81%94%E7%9B%B8%E4%B9%98%22%5D%0A%20%20SIX%20--%3E%20DARK%5B%22%E6%9A%97%E5%8C%BA%E8%A2%AB%E5%9E%AB%E9%AB%98%20flare%20%E5%BA%95%E5%BA%A7%22%5D%0A%20%20AGE%5B%22%E8%BF%90%E8%A1%8C%E4%B8%AD%E6%B0%A7%E5%8C%96%20%2F%20%E6%B0%A2%E8%87%B4%E8%B5%B7%E6%B3%A1%22%5D%20--%3E%20SIG2%5B%22%CF%83%20%E5%8F%98%E5%A4%A7%22%5D%0A%20%20SIG2%20--%3E%20DRIFT%5B%22flare%20%E6%A0%B8%E6%BC%82%E7%A7%BB%20%E5%85%A8%E5%9C%BA%20CD%20%E6%8C%87%E7%BA%B9%E8%B5%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：TIS ≈ (4πσ/λ)²。取 σ=0.2 nm、λ=13.5 nm，得约 (0.19)² ≈ 3%——单个面就散射掉百分之几的带内光；σ 恶化到 0.5 nm 时飙到 20% 以上。埃级粗糙不是洁癖，是对比度的直接税。</span></p><p><span class="marginnote">Zeiss 公开强调面形、MSFR、HSFR 分频管理。不要用一个 RMS 纳米数打天下——不同频段进不同的像质桶。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把低频面形的 Zernike 拟合写完，那是下一课。不重写 Kirk 测试步骤。出处：Gullikson EUV scatter；Naulleau 掩模/光学粗糙；Mack flare；Zeiss EUV 光学分频；Bakshi 多层界面。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多层粗糙同时降低峰值 \\(R\\) 并增加带内 TIS，短波把埃级高度放大成对比税。</li><li>空间频谱必须分段；清洗恢复不了溅射造成的中高频。</li><li>下一课专攻低频：镜面形状误差。</li><li>出处：Gullikson、Naulleau、Mack、Zeiss、Bakshi。</li></ul>',6))])}const I=A(d,[["render",m]]);export{T as __pageData,I as default};
